const label=document.getElementById('offline-status'),button=document.getElementById('refresh-offline');let reg,ready=false;
function status(){label.textContent=(ready?'Ready for offline use · Version 1.1':'Offline download not ready')+(navigator.onLine?' · Online':' · Offline');}
async function check(){const worker=reg?.active;if(!worker){ready=false;status();return;}const channel=new MessageChannel();const result=await new Promise(resolve=>{const timer=setTimeout(()=>resolve({ready:false}),5000);channel.port1.onmessage=e=>{clearTimeout(timer);resolve(e.data)};worker.postMessage('STATUS',[channel.port2]);});ready=Boolean(result.ready);status();if(reg.waiting){button.textContent='Install available update';label.textContent+=' · Update available';}else button.textContent=ready?'Check for updates':'Prepare offline use';}
if('serviceWorker' in navigator){try{reg=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});await navigator.serviceWorker.ready;await check();reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',()=>{if(reg.waiting)check();});});}catch{label.textContent='Offline download unavailable. Keep this page online and try again.';}}else{label.textContent='Offline use is not supported by this browser.';button.disabled=true;}
button.addEventListener('click',async()=>{try{if(reg?.waiting){reg.waiting.postMessage('ACTIVATE');return;}button.disabled=true;await navigator.storage?.persist?.();reg=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});await reg.update();await navigator.serviceWorker.ready;await check();}catch{label.textContent='Offline preparation failed. Reconnect and try again.';}finally{button.disabled=false;}});
navigator.serviceWorker?.addEventListener('controllerchange',()=>{if(reg?.active)location.reload();});window.addEventListener('online',status);window.addEventListener('offline',status);
